header('X-Content-Type-Options: nosniff'); header('Referrer-Policy: no-referrer'); header('X-Frame-Options: DENY');
$privateEnv=dirname(__DIR__,4).'/dcp-private/.env';
$envFile=getenv('DCP_CLOUD_ENV')?: (is_file($privateEnv)?$privateEnv:__DIR__.'/.env');
if(!is_file($envFile)){http_response_code(503);exit('DCP Cloud is not configured. Copy .env.example to .env and configure the database.');}
foreach(file($envFile, FILE_IGNORE_NEW_LINES|FILE_SKIP_EMPTY_LINES) as $line){$line=trim($line);if($line===''||$line[0]==='#'||!str_contains($line,'='))continue;[$k,$v]=explode('=',$line,2);putenv(trim($k).'='.trim($v," \\t\\n\\r\\0\\x0B\\\"'"));}
$appKey=(string)getenv('APP_KEY');
if(strlen($appKey)<32||preg_match('/[^\\x21-\\x7E]/',$appKey)||preg_match('/^(?:change[-_ ]?me|replace[-_ ]?with|your[-_ ]?key|example)/i',$appKey)){http_response_code(503);exit('DCP Cloud security key is not configured.');}
function db():PDO{static $pdo=null;if($pdo)return $pdo;$dsn='mysql:host='.getenv('DB_HOST').';port='.(getenv('DB_PORT')?:3306).';dbname='.getenv('DB_NAME').';charset=utf8mb4';return $pdo=new PDO($dsn,(string)getenv('DB_USER'),(string)getenv('DB_PASSWORD'),[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);}
function reply(int $status,array $data):never{http_response_code($status);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');echo json_encode($data,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);exit;}
set_exception_handler(static function(Throwable $e):void{error_log('[DCP Cloud] '.$e::class.': '.$e->getMessage());reply(503,['ok'=>false,'error'=>'cloud_backend_unavailable']);});
function input():array{$max=65536;$length=(int)($_SERVER['CONTENT_LENGTH']??0);if($length>$max)reply(413,['error'=>'request_body_too_large']);$raw=file_get_contents('php://input',false,null,0,$max+1)?:'{}';if(strlen($raw)>$max)reply(413,['error'=>'request_body_too_large']);$v=json_decode($raw,true);return is_array($v)?$v:reply(400,['error'=>'invalid_json']);}
function uuid():string{$b=random_bytes(16);$b[6]=chr((ord($b[6])&15)|64);$b[8]=chr((ord($b[8])&63)|128);$h=bin2hex($b);return substr($h,0,8).'-'.substr($h,8,4).'-'.substr($h,12,4).'-'.substr($h,16,4).'-'.substr($h,20);}
require_once __DIR__.'/token.php';
function hash_token(string $t):string{return dcp_cloud_hash_token($t,(string)getenv('APP_KEY'));}
function hash_token_candidates(string $t):array{return dcp_cloud_hash_token_candidates($t,(string)getenv('APP_KEY'),(string)getenv('APP_KEY_PREVIOUS'));}
function rate_limit(string $bucket,int $limit,int $windowSeconds):void{
 $ip=(string)($_SERVER['REMOTE_ADDR']??'unknown');
 $slot=intdiv(time(),$windowSeconds);
 $key=hash_hmac('sha256',$bucket.'|'.$ip.'|'.$slot,(string)getenv('APP_KEY'));
 db()->prepare('INSERT INTO api_rate_limits(bucket_key,hits,expires_at) VALUES(?,1,FROM_UNIXTIME(?)) ON DUPLICATE KEY UPDATE hits=hits+1')->execute([$key,($slot+1)*$windowSeconds]);
 $q=db()->prepare('SELECT hits FROM api_rate_limits WHERE bucket_key=?');$q->execute([$key]);
 if((int)$q->fetchColumn()>$limit){header('Retry-After',(string)max(1,(($slot+1)*$windowSeconds)-time()));reply(429,['error'=>'rate_limit_exceeded','retry_after'=>max(1,(($slot+1)*$windowSeconds)-time())]);}
}
function cleanup_expired():void{if(random_int(1,100)!==1)return;$pdo=db();foreach([
 'DELETE FROM signaling_messages WHERE expires_at<NOW()',
 'DELETE FROM connection_requests WHERE expires_at<NOW()',
 'DELETE FROM pairing_requests WHERE expires_at<NOW() OR (status IN (\'accepted\',\'rejected\') AND decided_at<DATE_SUB(NOW(),INTERVAL 7 DAY))',
 'DELETE FROM pairing_codes WHERE expires_at<NOW()',
 'DELETE FROM guest_invites WHERE expires_at<NOW()',
 'DELETE FROM api_tokens WHERE expires_at<NOW()',
 'DELETE FROM api_rate_limits WHERE expires_at<NOW()'
] as $sql)$pdo->exec($sql);}
function bearer():string{$h=$_SERVER['HTTP_AUTHORIZATION']??'';return preg_match('/^Bearer\s+(.+)$/i',$h,$m)?trim($m[1]):'';}
function auth_user():array{$t=bearer();if(strlen($t)<40)reply(401,['error'=>'unauthorized']);$hashes=hash_token_candidates($t);$in=implode(',',array_fill(0,count($hashes),'?'));$q=db()->prepare("SELECT a.id AS api_token_id,a.token_hash,u.* FROM api_tokens a JOIN users u ON u.id=a.user_id WHERE a.token_hash IN ($in) AND a.expires_at>NOW() LIMIT 1");$q->execute($hashes);$u=$q->fetch();if(!$u)reply(401,['error'=>'unauthorized']);if(!hash_equals((string)$u['token_hash'],hash_token($t)))db()->prepare('UPDATE api_tokens SET token_hash=? WHERE id=?')->execute([hash_token($t),$u['api_token_id']]);unset($u['api_token_id'],$u['token_hash']);return $u;}
function auth_device():array{$t=bearer();if(strlen($t)<40)reply(401,['error'=>'unauthorized']);$hashes=hash_token_candidates($t);$in=implode(',',array_fill(0,count($hashes),'?'));$q=db()->prepare("SELECT * FROM devices WHERE token_hash IN ($in) AND revoked_at IS NULL LIMIT 1");$q->execute($hashes);$d=$q->fetch();if(!$d)reply(401,['error'=>'unauthorized']);if(!hash_equals((string)$d['token_hash'],hash_token($t)))db()->prepare('UPDATE devices SET token_hash=? WHERE id=?')->execute([hash_token($t),$d['id']]);db()->prepare('UPDATE devices SET last_seen_at=NOW() WHERE id=?')->execute([$d['id']]);return $d;}
function has_pair_scope(string $a,string $b,string $scope):bool{$q=db()->prepare('SELECT p.scopes FROM device_pairings p JOIN devices a ON a.id=p.owner_device AND a.revoked_at IS NULL JOIN devices b ON b.id=p.peer_device AND b.revoked_at IS NULL WHERE p.revoked_at IS NULL AND ((p.owner_device=? AND p.peer_device=?) OR (p.owner_device=? AND p.peer_device=?)) LIMIT 1');$q->execute([$a,$b,$b,$a]);$raw=$q->fetchColumn();$scopes=is_string($raw)?json_decode($raw,true):[];return is_array($scopes)&&in_array($scope,$scopes,true);}
function issue_user_token(int $uid):string{$t=bin2hex(random_bytes(32));db()->prepare('INSERT INTO api_tokens(user_id,token_hash,expires_at) VALUES(?,?,DATE_ADD(NOW(),INTERVAL 30 DAY))')->execute([$uid,hash_token($t)]);return $t;}
