if($path==='/api/v1/health'&&$method==='GET'){try{$pdo=db();$pdo->query('SELECT 1')->fetchColumn();foreach(['users','api_tokens','devices','connection_requests','signaling_messages','pairing_codes','pairing_requests','device_pairings','api_rate_limits'] as $table)$pdo->query('SELECT 1 FROM `'.$table.'` LIMIT 0');reply(200,['ok'=>true,'database'=>'ok','schema'=>'ok','service'=>'DCP Cloud','relay'=>false,'transport'=>'signaling-only']);}catch(Throwable $e){error_log('[DCP Cloud health] '.$e->getMessage());reply(503,['ok'=>false,'database'=>'unavailable','schema'=>'unverified','service'=>'DCP Cloud']);}}
