if($path==='/api/v1/devices/anonymous/register'&&$method==='POST'){rate_limit('anonymous-device-register',20,3600);$b=input();$id=uuid();$token=bin2hex(random_bytes(32));db()->prepare('INSERT INTO devices(id,user_id,label,platform,token_hash,last_seen_at) VALUES(?,NULL,?,?,?,NOW())')->execute([$id,mb_substr(trim((string)($b['label']??'DCP Device')),0,120),mb_substr((string)($b['platform']??'unknown'),0,40),hash_token($token)]);reply(201,['device_id'=>$id,'device_token'=>$token,'identity'=>'anonymous']);}
if($path==='/api/v1/devices/link-account'&&$method==='POST'){rate_limit('device-link-account',20,3600);$d=auth_device();$b=input();$accountToken=(string)($b['account_token']??'');if(strlen($accountToken)<40)reply(401,['error'=>'invalid_account_token']);$accountHashes=hash_token_candidates($accountToken);$in=implode(',',array_fill(0,count($accountHashes),'?'));$q=db()->prepare("SELECT id,user_id,token_hash FROM api_tokens WHERE token_hash IN ($in) AND expires_at>NOW() LIMIT 1");$q->execute($accountHashes);$account=$q->fetch();if(!$account)reply(401,['error'=>'invalid_account_token']);if(!hash_equals((string)$account['token_hash'],hash_token($accountToken)))db()->prepare('UPDATE api_tokens SET token_hash=? WHERE id=?')->execute([hash_token($accountToken),$account['id']]);$uid=$account['user_id'];if($d['user_id']!==null&&(int)$d['user_id']!==(int)$uid)reply(409,['error'=>'device_already_linked_to_another_account']);db()->prepare('UPDATE devices SET user_id=? WHERE id=?')->execute([(int)$uid,$d['id']]);reply(200,['ok'=>true,'device_id'=>$d['id'],'account_linked'=>true]);}
