if($path==='/api/v1/pairing-requests'&&$method==='POST'){rate_limit('pairing-request',30,3600);$d=auth_device();$b=input();$code=strtoupper(trim((string)($b['code']??'')));$codeHashes=hash_token_candidates($code);$in=implode(',',array_fill(0,count($codeHashes),'?'));$q=db()->prepare("SELECT pc.id,pc.owner_device,pc.code_hash FROM pairing_codes pc JOIN devices owner ON owner.id=pc.owner_device AND owner.revoked_at IS NULL WHERE pc.code_hash IN ($in) AND pc.used_at IS NULL AND pc.expires_at>NOW() LIMIT 1");$q->execute($codeHashes);$invite=$q->fetch();if(!$invite)reply(404,['error'=>'pairing_code_invalid_or_expired']);if(!hash_equals((string)$invite['code_hash'],hash_token($code)))db()->prepare('UPDATE pairing_codes SET code_hash=? WHERE id=?')->execute([hash_token($code),$invite['id']]);if($invite['owner_device']===$d['id'])reply(422,['error'=>'cannot_pair_device_with_itself']);$id=uuid();db()->prepare("INSERT INTO pairing_requests(id,pairing_code_id,owner_device,requester_device,status,expires_at) VALUES(?,?,?,?,'pending',DATE_ADD(NOW(),INTERVAL 10 MINUTE))")->execute([$id,$invite['id'],$invite['owner_device'],$d['id']]);db()->prepare('UPDATE pairing_codes SET used_at=NOW() WHERE id=?')->execute([$invite['id']]);reply(201,['request_id'=>$id,'status'=>'pending','message'=>'Pairing request sent. The other device must approve it.']);}
if($path==='/api/v1/pairing-requests'&&$method==='GET'){rate_limit('pairing-request-list',240,60);$d=auth_device();$q=db()->prepare("SELECT r.id,r.requester_device,r.status,r.created_at,r.expires_at,x.label,x.platform FROM pairing_requests r JOIN devices x ON x.id=r.requester_device WHERE r.owner_device=? AND r.status='pending' AND r.expires_at>NOW() AND x.revoked_at IS NULL ORDER BY r.created_at");$q->execute([$d['id']]);reply(200,['requests'=>$q->fetchAll()]);}
if(preg_match('#^/api/v1/pairing-requests/([a-f0-9-]{36})/decision$#',$path,$m)&&$method==='POST'){
 rate_limit('pairing-decision',60,3600);$d=auth_device();$b=input();$q=db()->prepare("SELECT r.* FROM pairing_requests r JOIN devices requester ON requester.id=r.requester_device AND requester.revoked_at IS NULL WHERE r.id=? AND r.owner_device=? AND r.status='pending' AND r.expires_at>NOW()");$q->execute([$m[1],$d['id']]);$r=$q->fetch();if(!$r)reply(404,['error'=>'pairing_request_not_found_or_expired']);$accept=($b['accept']??false)===true;
