if($path==='/api/v1/paired-devices'&&$method==='GET'){rate_limit('paired-device-list',240,60);$d=auth_device();$q=db()->prepare('SELECT x.id,x.label,x.platform,x.last_seen_at,IF(x.last_seen_at>DATE_SUB(NOW(),INTERVAL 90 SECOND),1,0) online,p.scopes FROM device_pairings p JOIN devices x ON x.id=IF(p.owner_device=?,p.peer_device,p.owner_device) WHERE (p.owner_device=? OR p.peer_device=?) AND p.revoked_at IS NULL AND x.revoked_at IS NULL ORDER BY x.label');$q->execute([$d['id'],$d['id'],$d['id']]);$rows=$q->fetchAll();foreach($rows as &$row){$scopes=json_decode((string)$row['scopes'],true)?:[];$row['presence_enabled']=in_array('presence',$scopes,true);if(!$row['presence_enabled']){$row['last_seen_at']=null;$row['online']=null;}}unset($row);reply(200,['devices'=>$rows]);}
