if($path==='/api/v1/connections/request'&&$method==='POST'){rate_limit('connection-request',120,3600);$d=auth_device();$b=input();$target=(string)($b['target_device']??'');$q=db()->prepare('SELECT id,user_id FROM devices WHERE id=? AND revoked_at IS NULL');$q->execute([$target]);$peer=$q->fetch();if(!$peer||!has_pair_scope($d['id'],$target,'signaling'))reply(403,['error'=>'pairing_approval_and_signaling_permission_required']);$id=uuid();db()->prepare("INSERT INTO connection_requests(id,source_device,target_device,status,expires_at) VALUES(?,?,?,'pending',DATE_ADD(NOW(),INTERVAL 90 SECOND))")->execute([$id,$d['id'],$target]);reply(201,['request_id'=>$id,'expires_in'=>90]);}
if(preg_match('#^/api/v1/connections/([a-f0-9-]{36})/signal$#',$path,$m)&&$method==='POST'){rate_limit('signal-send',120,60);$d=auth_device();$b=input();$payload=(string)($b['envelope']??'');if($payload===''||strlen($payload)>32768)reply(422,['error'=>'invalid_envelope']);$q=db()->prepare('SELECT r.source_device,r.target_device FROM connection_requests r JOIN devices a ON a.id=r.source_device JOIN devices z ON z.id=r.target_device WHERE r.id=? AND r.expires_at>NOW() AND a.revoked_at IS NULL AND z.revoked_at IS NULL');$q->execute([$m[1]]);$c=$q->fetch();if(!$c||!in_array($d['id'],[$c['source_device'],$c['target_device']],true)||!has_pair_scope($c['source_device'],$c['target_device'],'signaling'))reply(404,['error'=>'request_not_found']);$to=$d['id']===$c['source_device']?$c['target_device']:$c['source_device'];db()->prepare('INSERT INTO signaling_messages(request_id,sender_device,recipient_device,envelope,expires_at) VALUES(?,?,?,?,DATE_ADD(NOW(),INTERVAL 180 SECOND))')->execute([$m[1],$d['id'],$to,$payload]);reply(202,['accepted'=>true,'delivery'=>'signaling_only']);}
if(preg_match('#^/api/v1/connections/([a-f0-9-]{36})/signals$#',$path,$m)&&$method==='GET'){rate_limit('signal-poll',240,60);$d=auth_device();$rq=db()->prepare("SELECT r.source_device,r.target_device FROM connection_requests r JOIN devices a ON a.id=r.source_device AND a.revoked_at IS NULL JOIN devices z ON z.id=r.target_device AND z.revoked_at IS NULL WHERE r.id=? AND r.expires_at>NOW() AND r.status='pending'");$rq->execute([$m[1]]);$pair=$rq->fetch();if(!$pair||!in_array($d['id'],[$pair['source_device'],$pair['target_device']],true)||!has_pair_scope($pair['source_device'],$pair['target_device'],'signaling'))reply(404,['error'=>'request_not_found']);$after=max(0,(int)($_GET['after']??0));$s=db()->prepare('SELECT id,sender_device,envelope,created_at FROM signaling_messages WHERE request_id=? AND recipient_device=? AND id>? AND expires_at>NOW() ORDER BY id LIMIT 50');$s->execute([$m[1],$d['id'],$after]);reply(200,['signals'=>$s->fetchAll()]);}
reply(404,['error'=>'not_found']);
